// Des: Tests for ru-page-fetc: store once, 304, dedupe, UTF-8, errors
// Flo: mock server + temp dir > run pipeline repeatedly > assert stat words, files, rows
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const pipe = @import("ru-page-fetc.zig"); const inde = @import("st-page-inde.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const mock = @import("te-mock-serv.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rig = struct { tmpz: std.testing.TmpDir, srv: mock.Mock, dirz: []u8, dbzz: @import("st-stor-sqli.zig").Db, aren: std.heap.ArenaAllocator, pub fn up(self: *Rig) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv.start(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); } pub fn down(self: *Rig) void { self.aren.deinit(); self.dbzz.close(); self.srv.halt(); allo.free(self.dirz); self.tmpz.cleanup(); } pub fn go(self: *Rig, path: []const u8) !pipe.Outc { var buf: [64]u8 = undefined; return pipe.pageFetc(allo, self.aren.allocator(), std.testing.io, .{}, &self.dbzz, self.dirz, self.srv.urlOf(&buf, path), true); } };
test "first fetch stores once, refetch is 304, no new file" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const one = try rig.go("/cond"); try std.testing.expectEqualStrings("new", one.stat); try std.testing.expectEqual(@as(u16, 200), one.code); const two = try rig.go("/cond"); try std.testing.expectEqualStrings("notm", two.stat); try std.testing.expectEqual(@as(u16, 304), two.code); try std.testing.expectEqualStrings(one.hexz, two.hexz); try std.testing.expectEqual(@as(i64, 2), try inde.logzCont(&rig.dbzz)); }
test "same body without etag: second run is same, stored once" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const one = try rig.go("/gz"); try std.testing.expectEqualStrings("new", one.stat); const two = try rig.go("/gz"); try std.testing.expectEqualStrings("same", two.stat); try std.testing.expectEqualStrings(one.hexz, two.hexz); }
test "latin1 page is stored as UTF-8" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const one = try rig.go("/latin"); try std.testing.expectEqualStrings("new", one.stat); var hx: hash.Hexz = undefined; @memcpy(&hx, one.hexz[0..64]); const rawd = try std.fs.path.join(allo, &.{ rig.dirz, "raw" }); defer allo.free(rawd); const back = try file.fileLoad(allo, std.testing.io, rawd, hx, 1000); defer allo.free(back); try std.testing.expectEqualStrings("caf\xC3\xA9", back); }
test "non-2xx is logged, never stored" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const one = try rig.go("/e403"); try std.testing.expectEqualStrings("http", one.stat); try std.testing.expectEqual(@as(u16, 403), one.code); try std.testing.expect(try inde.pageGet(&rig.dbzz, rig.aren.allocator(), one.urlz) == null); try std.testing.expectEqual(@as(i64, 1), try inde.logzCont(&rig.dbzz)); }
test "errors are logged and returned typed" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectError(error.NotText, rig.go("/img")); try std.testing.expectError(error.RedirectLoop, rig.go("/loop")); try std.testing.expectEqual(@as(i64, 2), try inde.logzCont(&rig.dbzz)); }
test "crash after file write, before index: rerun is idempotent" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const rawd = try std.fs.path.join(allo, &.{ rig.dirz, "raw" }); defer allo.free(rawd); const orph = try file.fileSave(allo, std.testing.io, rawd, "<html>hello</html>"); try std.testing.expect(orph.fresh); const one = try rig.go("/ok"); try std.testing.expectEqualStrings("new", one.stat); try std.testing.expectEqualStrings(&orph.hexz, one.hexz); const two = try rig.go("/ok"); try std.testing.expectEqualStrings("same", two.stat); }
